#pragma once

// Независимый (от нашего порта OpenMPT в formats/it_decompress.h)
// декодер IT-компрессии сэмплов для golden-теста: сверка результата двух
// разных реализаций одного формата.
//
// Источник алгоритма: libxmp src/loaders/itsex.c ("Public domain IT
// sample decompressor by Olivier Lapicque", доработан Alice Rowan,
// 2023-2024). Автор тот же, что стоял у истоков ModPlug/OpenMPT, но
// кодовая база с тех пор сопровождается независимо: другая структура
// (чтение 32-битными словами через свой маленький bit-reader, а не через
// LSB-first BitReader, как у OpenMPT; другие производные пороговые
// константы в режимах B/C) при той же арифметике формата - то, что нужно
// для содержательной сверки. Public domain - копирование и адаптация без
// ограничений, указание источника оставляем.
//
// Не часть soundsinth_core - только PC-тесты (backend/ports/pc/tests/). Файл
// самодостаточен, исходники libxmp для сборки не нужны.
//
// Адаптация относительно оригинала: убран HIO_HANDLE (файловый ввод
// libxmp), вместо него декодер работает с уже прочитанным в память
// буфером одного блока (2-байтный префикс длины блока читает вызывающий
// код, как и для formats::it::decompress_step - одно соглашение для обеих
// сторон сверки). Арифметика (read_bits, автомат распаковки) не
// менялась.

#include <cstdint>

namespace libxmp_itsex {

// bitstream/bitstream_bytes - сжатые данные одного блока (без 2-байтного
// префикса длины, его читает вызывающий код, как у
// soundsinth::formats::it::decompress_step). len - сколько сэмплов
// декодировать, весь блок сразу: в отличие от нашего потокового
// decompress_step, оригинальный itsex не возобновляемый, но вызывается
// только в тестах на отдельные блоки. dst - сырой диапазон (8 бит:
// -128..127, без масштабирования *256 - то же соглашение, что у нашего
// порта, для прямой побайтовой сверки). it215 - второй порядок
// накопления (IT2.15+). Возвращает 0 при успехе, отрицательное число -
// если во входных данных не хватило байт на заявленную длину блока.
int decompress8(const uint8_t* bitstream, uint32_t bitstream_bytes, int8_t* dst, int len, int it215);
int decompress16(const uint8_t* bitstream, uint32_t bitstream_bytes, int16_t* dst, int len, int it215);

} // namespace libxmp_itsex
